set -u
R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p
mkdir -p $R/sb_fprev; cp $R/sb_cursor_probe/AGENTS.md $R/sb_fprev/AGENTS.md
echo  | base64 -d > $R/sb_fprev/PROMPT.md
cd $R/sb_fprev && tmux new-session -d -s sb_fprev "timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 5; tmux ls | cut -d: -f1 | tr "\n" " "; echo
cat $R/sb_queue/queue.txt | tr "\n" " "; echo
sha256sum $R/sb_framepool/out/sb_framepool.tar $R/sb_rowB3/out/sb_rowB3.tar $R/sb_rowLR/out/sb_rowLR.tar $R/sb_auditfix/out/sb_auditfix.tar | cut -c1-80
